<?php
namespace App\Http\Controllers;
use App\Models\AccountPayout; use App\Models\Book; use App\Models\BookActivityDailyMetric; use App\Models\User; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class StatisticsController extends Controller { public function index(Request $request): JsonResponse { $user=$this->user($request);$data=$request->validate(['period'=>['nullable','integer','in:28,90,365']]);$days=$data['period']??90;$from=now()->subDays($days-1)->toDateString();$books=Book::query()->where('account_id',$user->id)->get(['id','key_book','name','cover_img']);$metrics=BookActivityDailyMetric::query()->whereIn('book_id',$books->pluck('id'))->where('metric_date','>=',$from)->get();$gross=(int)$metrics->sum('revenue_cents');$payouts=AccountPayout::query()->where('account_id',$user->id)->latest()->get();$paid=(int)$payouts->where('status','paid')->sum('amount_cents');$pending=(int)$payouts->whereIn('status',['pending','processing'])->sum('amount_cents');return response()->json(['data'=>['period'=>$days,'summary'=>['gross_cents'=>$gross,'paid_cents'=>$paid,'pending_cents'=>$pending,'available_cents'=>max(0,$gross-$paid-$pending)],'books'=>$books->map(function($book)use($metrics){$set=$metrics->where('book_id',$book->id);return ['key'=>$book->key_book,'name'=>$book->name,'cover_img'=>$book->cover_img,'revenue_cents'=>(int)$set->sum('revenue_cents'),'plays'=>(int)$set->sum('plays'),'revenue_per_play_cents'=>$set->sum('plays')?round($set->sum('revenue_cents')/$set->sum('plays'),2):0];})->sortByDesc('revenue_cents')->values(),'payouts'=>$payouts->take(8)->map(fn($p)=>['id'=>$p->id,'amount_cents'=>$p->amount_cents,'currency'=>$p->currency,'status'=>$p->status,'paid_at'=>$p->paid_at?->toISOString(),'created_at'=>$p->created_at?->toISOString()])->values(),'payouts_ready'=>false]]); } private function user(Request $request): User {$user=$request->user();abort_unless($user,401,'Please sign in to view statistics.');return $user;} }
